package io.knowledgebrain.knowledge;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_KNOWLEDGE_DATABASE_URL",matches=".+")
class PublicRecordStoreIntegrationTest {
    PublicRecordStore store;ConceptStore concepts;JdbcTemplate jdbc;UUID space,author,reviewer,subject,predicate,object;long sequence=0;String trace="e".repeat(32);UuidV7 ids=new UuidV7(Clock.systemUTC());JsonMapper json=JsonMapper.builder().build();
    @BeforeEach void setup(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_URL"));ds.setUser("brain_knowledge");ds.setPassword(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();store=new PublicRecordStore(ds,Clock.systemUTC());concepts=new ConceptStore(ds,Clock.systemUTC());jdbc=new JdbcTemplate(ds);space=ids.next();author=ids.next();reviewer=ids.next();subject=publicConcept("Subject");predicate=publicConcept("Related to");object=publicConcept("Object");}
    UUID publicConcept(String title){return concepts.createWithId(space,ids.next(),reviewer,title,"",trace,"PUBLIC").conceptId();}
    JsonNode node(Object... values){var n=json.createObjectNode();for(int i=0;i<values.length;i+=2){String k=(String)values[i];Object v=values[i+1];if(v instanceof Number number)n.put(k,number.longValue());else n.put(k,v.toString());}return n;}
    JsonNode claim(){return node("subjectId",subject,"subjectVersion",1,"predicateId",predicate,"predicateVersion",1,"objectType","CONCEPT","objectValue",object,"objectVersion",1);}
    JsonNode source(){return node("title","Source","url","https://example.org/source","citation","Original metadata","licenseNote","Metadata only; no full text copied");}
    JsonNode alias(String label){return node("conceptId",subject,"conceptVersion",1,"label",label,"scope","COUNTRY","scopeValue","KR");}
    PublicRecordStore.Proposal submit(String kind,JsonNode content){return store.submit(space,author,kind,"CREATE",null,0,"Public fact "+(++sequence),content,"Explicit public proposal",trace);}
    PublicRecordStore.Fact publish(String kind,JsonNode content){var p=submit(kind,content);store.decide(space,p.proposalId(),reviewer,1,"APPROVED","Reviewed",trace);store.decide(space,p.proposalId(),reviewer,2,"MERGED","Publish reviewed snapshot",trace);return store.get(space,p.recordId());}
    PublicRecordStore.Proposal update(PublicRecordStore.Fact prior,JsonNode content){return store.submit(space,author,prior.kind(),"UPDATE",prior.recordId(),prior.version(),prior.title(),content,"Explicit revision",trace);}
    void merge(PublicRecordStore.Proposal p){store.decide(space,p.proposalId(),reviewer,1,"APPROVED","Reviewed",trace);store.decide(space,p.proposalId(),reviewer,2,"MERGED","Merge",trace);}
    void status(Runnable action,int expected){assertThatThrownBy(action::run).isInstanceOf(ResponseStatusException.class).satisfies(e->assertThat(((ResponseStatusException)e).getStatusCode().value()).isEqualTo(expected));}
    @Test void immutableProposalReviewMergeCreatesRevisionAndTwoOutboxRows(){var p=submit("ALIAS",alias("Local alias"));assertThat(store.list(space,null,"ACTIVE",null,10,"").items()).isEmpty();status(()->store.decide(space,p.proposalId(),author,1,"APPROVED","Self",trace),403);store.decide(space,p.proposalId(),reviewer,1,"APPROVED","Checked",trace);assertThat(store.list(space,null,"ACTIVE",null,10,"").items()).isEmpty();store.decide(space,p.proposalId(),reviewer,2,"MERGED","Merge",trace);assertThat(store.get(space,p.recordId()).content().path("scope").asString()).isEqualTo("COUNTRY");assertThat(store.revisions(space,p.recordId(),Long.MAX_VALUE,10)).hasSize(1);assertThat(store.reviews(space,p.proposalId())).hasSize(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='public-record' AND aggregateid IN (?,?)",Integer.class,p.proposalId(),p.recordId())).isEqualTo(4);}
    @Test void crossSpaceAndPrivateConceptReferencesCannotPublish(){UUID privateId=concepts.create(space,author,"Private","Do not publish",trace).conceptId();var input=alias("Secret");((tools.jackson.databind.node.ObjectNode)input).put("conceptId",privateId.toString());status(()->submit("ALIAS",input),404);var p=submit("CLAIM",claim());status(()->store.proposal(ids.next(),p.proposalId()),404);assertThat(store.explore(space,"Private",null,20).items()).isEmpty();}
    @Test void staleApprovedProposalCannotOverwriteAndFailedOutboxRollsBackWholeMerge(){var original=publish("SOURCE",source());var edit=source();((tools.jackson.databind.node.ObjectNode)edit).put("title","Changed");var a=update(original,edit);var b=update(original,edit);merge(a);store.decide(space,b.proposalId(),reviewer,1,"APPROVED","Approved",trace);status(()->store.decide(space,b.proposalId(),reviewer,2,"MERGED","Merge",trace),412);var p=submit("ALIAS",alias("Rollback"));store.decide(space,p.proposalId(),reviewer,1,"APPROVED","Checked",trace);jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT public_record_test_rollback CHECK(type <> 'PublicProposalMerged') NOT VALID");try{assertThatThrownBy(()->store.decide(space,p.proposalId(),reviewer,2,"MERGED","Merge",trace)).isInstanceOf(org.springframework.dao.DataAccessException.class);status(()->store.get(space,p.recordId()),404);assertThat(store.proposal(space,p.proposalId()).state()).isEqualTo("APPROVED");assertThat(store.reviews(space,p.proposalId())).hasSize(1);}finally{jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT public_record_test_rollback");}}
    @Test void concurrentReviewsHaveOneWinnerAndRejectedCannotMerge()throws Exception{var p=submit("ALIAS",alias("Race"));try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CountDownLatch(1);var jobs=new ArrayList<Future<Integer>>();for(int i=0;i<4;i++)jobs.add(pool.submit(()->{barrier.await();try{store.decide(space,p.proposalId(),reviewer,1,"REJECTED","Fix",trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));barrier.countDown();var outcomes=new ArrayList<Integer>();for(var job:jobs)outcomes.add(job.get(20,TimeUnit.SECONDS));assertThat(Collections.frequency(outcomes,200)).isEqualTo(1);assertThat(outcomes).containsOnly(200,412);}status(()->store.decide(space,p.proposalId(),reviewer,2,"MERGED","Merge",trace),409);}
    @Test void allLiteralTypesValidateAndDuplicatesCannotMerge(){for(var values:List.of(new String[]{"STRING","literal"},new String[]{"NUMBER","1.500"},new String[]{"DATE","2026-11-01"},new String[]{"BOOLEAN","false"})){var v=(tools.jackson.databind.node.ObjectNode)claim();v.put("objectType",values[0]);v.put("objectValue",values[1]);v.put("objectVersion",0);assertThat(publish("CLAIM",v).content().path("objectType").asString()).isEqualTo(values[0]);}publish("ALIAS",alias("Unique"));var duplicate=submit("ALIAS",alias("Unique"));store.decide(space,duplicate.proposalId(),reviewer,1,"APPROVED","Reviewed",trace);status(()->store.decide(space,duplicate.proposalId(),reviewer,2,"MERGED","Merge",trace),409);}
    @Test void reviewedPinsAreRecheckedAtMergeAndOldHistoryRemains(){var c=publish("CLAIM",claim());var s=publish("SOURCE",source());var evidence=node("claimId",c.recordId(),"claimVersion",1,"sourceId",s.recordId(),"sourceVersion",1,"locator","Section1","explanation","Supports the exact statement");var pending=submit("EVIDENCE",evidence);merge(update(s,source()));store.decide(space,pending.proposalId(),reviewer,1,"APPROVED","Reviewed",trace);status(()->store.decide(space,pending.proposalId(),reviewer,2,"MERGED","Merge",trace),412);assertThat(store.revisions(space,s.recordId(),2,10).getFirst().version()).isEqualTo(1);}
    @Test void verificationCannotSkipStagesAndChangedClaimNeverInheritsIt(){var c=publish("CLAIM",claim());var s=publish("SOURCE",source());var e=publish("EVIDENCE",node("claimId",c.recordId(),"claimVersion",1,"sourceId",s.recordId(),"sourceVersion",1,"locator","Section1","explanation","Grounds"));var v=node("claimId",c.recordId(),"claimVersion",1,"evidenceId",e.recordId(),"evidenceVersion",1,"level","EXPERT_VERIFIED","reason","Reviewed");status(()->submit("VERIFICATION",v),400);((tools.jackson.databind.node.ObjectNode)v).put("level","SOURCED");var sourced=publish("VERIFICATION",v);assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("SOURCED");((tools.jackson.databind.node.ObjectNode)v).put("level","COMMUNITY_REVIEWED");merge(update(sourced,v));assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("COMMUNITY_REVIEWED");merge(update(c,claim()));assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("DRAFT");assertThat(store.revisions(space,sourced.recordId(),Long.MAX_VALUE,10)).hasSize(2);}
    @Test void evidenceRetirementInvalidatesEffectiveVerification(){var c=publish("CLAIM",claim());var s=publish("SOURCE",source());var e=publish("EVIDENCE",node("claimId",c.recordId(),"claimVersion",1,"sourceId",s.recordId(),"sourceVersion",1,"locator","p1","explanation","Grounds"));publish("VERIFICATION",node("claimId",c.recordId(),"claimVersion",1,"evidenceId",e.recordId(),"evidenceVersion",1,"level","SOURCED","reason","Checked"));var retire=store.submit(space,author,"EVIDENCE","RETIRE",e.recordId(),1,e.title(),json.createObjectNode(),"Retract invalid evidence",trace);merge(retire);assertThat(store.verification(space,c.recordId()).needsReview()).isTrue();assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("DRAFT");assertThat(store.revisions(space,e.recordId(),Long.MAX_VALUE,10)).hasSize(2);}
    @Test void mappingProgressionAndScopedAliasSearchAreIndependentOfVerification(){var s=publish("SOURCE",source());var m=node("conceptId",subject,"conceptVersion",1,"sourceId",s.recordId(),"sourceVersion",1,"system","Example","code","A1","systemVersion","2026","label","Label","mappingState","OFFICIAL","authority","Publisher provenance");status(()->submit("MAPPING",m),400);((tools.jackson.databind.node.ObjectNode)m).put("mappingState","CANDIDATE");var map=publish("MAPPING",m);((tools.jackson.databind.node.ObjectNode)m).put("mappingState","CONFIRMED");merge(update(map,m));publish("ALIAS",alias("Local searchable alias"));assertThat(store.explore(space,"searchable",null,20).items()).extracting(PublicRecordStore.ConceptCard::conceptId).containsExactly(subject);assertThat(store.relations(space,subject,20).claims()).isEmpty();}
    @Test void boundedPagesAndRelationsNeverIncludeUnmergedFacts(){publish("CLAIM",claim());submit("ALIAS",alias("Pending"));for(int i=0;i<4;i++)publish("SOURCE",source());var page=store.list(space,null,"ACTIVE",null,2,"");assertThat(page.items()).hasSize(2);assertThat(page.nextAfter()).isNotNull();assertThat(store.queue(space,"SUBMITTED",null,author,null,20).items()).hasSize(1);assertThat(store.relations(space,subject,20).concepts()).hasSize(3);assertThat(store.list(space,"ALIAS","ACTIVE",null,20,"Pending").items()).isEmpty();}
    @Test void identityTuplesHandleDelimitersAndLongUnicodeWithoutWideIndexFailure(){
        var a=(tools.jackson.databind.node.ObjectNode)alias("B|C");a.put("scope","ORGANIZATION");a.put("scopeValue","A");
        var b=(tools.jackson.databind.node.ObjectNode)alias("C");b.put("scope","ORGANIZATION");b.put("scopeValue","A|B");
        assertThat(publish("ALIAS",a).recordId()).isNotEqualTo(publish("ALIAS",b).recordId());
        var literal=(tools.jackson.databind.node.ObjectNode)claim();literal.put("objectType","STRING");literal.put("objectValue","知".repeat(1000));literal.put("objectVersion",0);
        assertThat(publish("CLAIM",literal).content().path("objectValue").asString()).hasSize(1000);
    }

    @Test void qualifierScopeChangesAndRetirementsRequireFreshVerification(){
        var c=publish("CLAIM",claim());var source=publish("SOURCE",source());var e=publish("EVIDENCE",node("claimId",c.recordId(),"claimVersion",1,"sourceId",source.recordId(),"sourceVersion",1,"locator","p1","explanation","Grounds"));
        var content=node("claimId",c.recordId(),"claimVersion",1,"evidenceId",e.recordId(),"evidenceVersion",1,"level","SOURCED","reason","Checked exact scope");var assessment=publish("VERIFICATION",content);((tools.jackson.databind.node.ObjectNode)content).put("level","COMMUNITY_REVIEWED");merge(update(assessment,content));assessment=store.get(space,assessment.recordId());
        var q=publish("QUALIFIER",node("claimId",c.recordId(),"claimVersion",1,"predicateId",predicate,"predicateVersion",1,"valueType","NUMBER","value","18.00","valueVersion",0));assertThat(q.content().path("value").asString()).isEqualTo("18");assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("DRAFT");assertThat(store.verification(space,c.recordId()).needsReview()).isTrue();
        var current=assessment;status(()->update(current,content),412);var pins=store.qualifierPins(space,c.recordId(),1);status(()->store.submit(space,author,"VERIFICATION","UPDATE",current.recordId(),current.version(),current.title(),content,"Changed scope",trace,pins),400);
        ((tools.jackson.databind.node.ObjectNode)content).put("level","SOURCED");var p=store.submit(space,author,"VERIFICATION","UPDATE",current.recordId(),current.version(),current.title(),content,"Re-sourced changed scope",trace,pins);merge(p);assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("SOURCED");
        var retire=store.submit(space,author,"QUALIFIER","RETIRE",q.recordId(),1,q.title(),json.createObjectNode(),"Retract scope",trace);merge(retire);assertThat(store.qualifiers(space,c.recordId())).extracting(PublicRecordStore.Fact::state).containsExactly("RETIRED");assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("DRAFT");assertThat(store.qualifierPins(space,c.recordId(),1).path(q.recordId().toString()).asLong()).isEqualTo(2);assertThat(store.revisions(space,current.recordId(),Long.MAX_VALUE,10).getFirst().qualifierPins().path(q.recordId().toString()).asLong()).isEqualTo(1);
        assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='public-knowledge' AND aggregateid=? AND type='PublicKnowledgeChanged'",Integer.class,q.recordId())).isEqualTo(2);
    }
    @Test void pendingQualifierMergeRechecksClaimRevisionAndPrivateValues(){var c=publish("CLAIM",claim());var q=node("claimId",c.recordId(),"claimVersion",1,"predicateId",predicate,"predicateVersion",1,"valueType","CONCEPT","value",object,"valueVersion",1);var pending=submit("QUALIFIER",q);merge(update(c,claim()));store.decide(space,pending.proposalId(),reviewer,1,"APPROVED","Inspect",trace);status(()->store.decide(space,pending.proposalId(),reviewer,2,"MERGED","Publish",trace),412);((tools.jackson.databind.node.ObjectNode)q).put("claimVersion",2);((tools.jackson.databind.node.ObjectNode)q).put("value",concepts.create(space,author,"Private value","",trace).conceptId().toString());status(()->submit("QUALIFIER",q),404);}
    @Test void normalizedCanonicalOutboxFailureRollsBackReviewedFact(){var p=submit("ALIAS",alias("Atomic normalized stream"));store.decide(space,p.proposalId(),reviewer,1,"APPROVED","Checked",trace);jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT public_discovery_test_atomic CHECK(type <> 'PublicKnowledgeChanged') NOT VALID");try{assertThatThrownBy(()->store.decide(space,p.proposalId(),reviewer,2,"MERGED","Merge",trace)).isInstanceOf(org.springframework.dao.DataAccessException.class);status(()->store.get(space,p.recordId()),404);assertThat(store.proposal(space,p.proposalId()).state()).isEqualTo("APPROVED");}finally{jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT public_discovery_test_atomic");}}

    @Test void referencedQualifierConceptChangesInvalidateVerificationWithoutChangingClaim(){var c=publish("CLAIM",claim());var scopePredicate=publicConcept("Distinct scope predicate");publish("QUALIFIER",node("claimId",c.recordId(),"claimVersion",1,"predicateId",scopePredicate,"predicateVersion",1,"valueType","STRING","value","Scoped value","valueVersion",0));var source=publish("SOURCE",source());var e=publish("EVIDENCE",node("claimId",c.recordId(),"claimVersion",1,"sourceId",source.recordId(),"sourceVersion",1,"locator","p1","explanation","Grounds"));var v=node("claimId",c.recordId(),"claimVersion",1,"evidenceId",e.recordId(),"evidenceVersion",1,"level","SOURCED","reason","Inspected scope");merge(store.submit(space,author,"VERIFICATION","CREATE",null,0,"Scoped assessment",v,"Explicit scope",trace,store.qualifierPins(space,c.recordId(),1)));assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("SOURCED");concepts.changeScoped(space,scopePredicate,reviewer,1,"Changed scope predicate","New meaning",false,trace,"PUBLIC");assertThat(store.get(space,c.recordId()).version()).isEqualTo(1);assertThat(store.verification(space,c.recordId()).effectiveLevel()).isEqualTo("DRAFT");assertThat(store.verification(space,c.recordId()).needsReview()).isTrue();}

}
